"/* ════════════════════════════════════════════════════════════
   BREW & BLOOM CAFÉ — style.css
   PREMIUM HIGH-CONTRAST PALETTE:
   --forest-green:   #073B32  (primary deep forest green)
   --forest-dark:    #042620  (darker forest tone)
   --espresso:       #172421  (dark espresso / text & dark bg)
   --espresso-2:     #0F1916  (deep charcoal espresso)
   --vibrant-orange: #FF7629  (primary CTA & accent)
   --golden-yellow:  #FFC247  (secondary CTA & bestseller tag)
   --warm-cream:     #FFF8EC  (menu background & base surface)
   --cream-soft:     #F7EEDD  (subtle card & hover tone)
   --fresh-mint:     #D9F3E5  (accent badge & fresh indicator)
   --mint-dark:      #1B7552  (mint text for contrast)
   --coral-pink:     #FF6B6B  (promo banner & special tags)
   --lavender:       #E5DBFF  (soft promo banner & special card)
   --white:          #FFFFFF  (pure white card surfaces)
   --text-dark:      #172421  (high contrast text on cream)
   --text-muted:     #52605C  (secondary body text)
   --text-light:     #FFF8EC  (text on dark surfaces)
   ════════════════════════════════════════════════════════════ */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
